-- =====================================================================
-- H2 建表脚本（MODE=MySQL，用于本地开发与单元测试）
-- 与 db/schema.sql（MySQL 8 版）保持同构，差异只在方言：
--   AUTO_INCREMENT -> GENERATED BY DEFAULT AS IDENTITY
--   DATETIME       -> TIMESTAMP          TEXT -> CLOB
-- 脚本必须幂等：CREATE TABLE IF NOT EXISTS + data.sql 用 MERGE，重启不会重复插数据
-- 时间字段统一走数据库默认值，避免应用与库时间不一致
-- =====================================================================

-- ---------------------------------------------------------------------
-- 系统 / 权限（RBAC）
-- ---------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS sys_user (
    id            BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    username      VARCHAR(64)  NOT NULL,
    password      VARCHAR(200) NOT NULL,
    nickname      VARCHAR(64)  NOT NULL,
    avatar        VARCHAR(500),
    phone         VARCHAR(20),
    status        INT          NOT NULL DEFAULT 1,
    source        VARCHAR(16)  NOT NULL DEFAULT 'web',
    openid        VARCHAR(64),
    last_login_at TIMESTAMP,
    created_at    TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at    TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted       INT          NOT NULL DEFAULT 0
);
CREATE UNIQUE INDEX IF NOT EXISTS uk_sys_user_username ON sys_user (username);
CREATE INDEX IF NOT EXISTS idx_sys_user_openid ON sys_user (openid);

CREATE TABLE IF NOT EXISTS sys_role (
    id         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    code       VARCHAR(64) NOT NULL,
    name       VARCHAR(64) NOT NULL,
    remark     VARCHAR(255),
    sort       INT         NOT NULL DEFAULT 0,
    created_at TIMESTAMP   NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE UNIQUE INDEX IF NOT EXISTS uk_sys_role_code ON sys_role (code);

CREATE TABLE IF NOT EXISTS sys_user_role (
    id      BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id BIGINT NOT NULL,
    role_id BIGINT NOT NULL
);
CREATE UNIQUE INDEX IF NOT EXISTS uk_sys_user_role ON sys_user_role (user_id, role_id);

CREATE TABLE IF NOT EXISTS sys_menu (
    id         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    parent_id  BIGINT      NOT NULL DEFAULT 0,
    name       VARCHAR(64) NOT NULL,
    path       VARCHAR(200),
    component  VARCHAR(200),
    icon       VARCHAR(64),
    type       INT         NOT NULL DEFAULT 1,
    perm       VARCHAR(100),
    sort       INT         NOT NULL DEFAULT 0,
    hidden     INT         NOT NULL DEFAULT 0,
    created_at TIMESTAMP   NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_sys_menu_parent ON sys_menu (parent_id);

CREATE TABLE IF NOT EXISTS sys_role_menu (
    id      BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    role_id BIGINT NOT NULL,
    menu_id BIGINT NOT NULL
);
CREATE UNIQUE INDEX IF NOT EXISTS uk_sys_role_menu ON sys_role_menu (role_id, menu_id);

-- ---------------------------------------------------------------------
-- 内容中心
-- ---------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS cms_category (
    id         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name       VARCHAR(64) NOT NULL,
    code       VARCHAR(64) NOT NULL,
    parent_id  BIGINT      NOT NULL DEFAULT 0,
    sort       INT         NOT NULL DEFAULT 0,
    status     INT         NOT NULL DEFAULT 1,
    deleted    INT         NOT NULL DEFAULT 0,
    created_at TIMESTAMP   NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE UNIQUE INDEX IF NOT EXISTS uk_cms_category_code ON cms_category (code);

CREATE TABLE IF NOT EXISTS cms_content (
    id           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    title        VARCHAR(200) NOT NULL,
    summary      VARCHAR(500),
    body         CLOB,
    cover_url    VARCHAR(500),
    category_id  BIGINT,
    content_type VARCHAR(16)  NOT NULL DEFAULT 'article',
    status       INT          NOT NULL DEFAULT 0,
    top_flag     INT          NOT NULL DEFAULT 0,
    sort         INT          NOT NULL DEFAULT 0,
    author_id    BIGINT,
    author_name  VARCHAR(64),
    publish_time TIMESTAMP,
    view_count   BIGINT       NOT NULL DEFAULT 0,
    deleted      INT          NOT NULL DEFAULT 0,
    created_at   TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at   TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_cms_content_status ON cms_content (status, deleted);
CREATE INDEX IF NOT EXISTS idx_cms_content_category ON cms_content (category_id);
CREATE INDEX IF NOT EXISTS idx_cms_content_publish ON cms_content (publish_time);

CREATE TABLE IF NOT EXISTS cms_tag (
    id         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name       VARCHAR(64) NOT NULL,
    -- 运营在富文本编辑器里随手输入的标签没有英文 slug，因此 code 允许为空
    code       VARCHAR(64),
    created_at TIMESTAMP   NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE UNIQUE INDEX IF NOT EXISTS uk_cms_tag_code ON cms_tag (code);

CREATE TABLE IF NOT EXISTS cms_content_tag (
    id         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    content_id BIGINT NOT NULL,
    tag_id     BIGINT NOT NULL
);
CREATE UNIQUE INDEX IF NOT EXISTS uk_cms_content_tag ON cms_content_tag (content_id, tag_id);

-- ---------------------------------------------------------------------
-- 地理 / 点位（文旅资源 + 遥感地块）
-- ---------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS geo_region (
    id         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name       VARCHAR(64) NOT NULL,
    code       VARCHAR(64) NOT NULL,
    parent_id  BIGINT      NOT NULL DEFAULT 0,
    level      INT         NOT NULL DEFAULT 1,
    center_lng DOUBLE,
    center_lat DOUBLE,
    created_at TIMESTAMP   NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE UNIQUE INDEX IF NOT EXISTS uk_geo_region_code ON geo_region (code);

CREATE TABLE IF NOT EXISTS geo_point (
    id         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name       VARCHAR(100) NOT NULL,
    region_id  BIGINT,
    type       VARCHAR(16)  NOT NULL DEFAULT 'scenic',
    lng        DOUBLE       NOT NULL,
    lat        DOUBLE       NOT NULL,
    address    VARCHAR(255),
    cover_url  VARCHAR(500),
    summary    VARCHAR(1000),
    status     INT          NOT NULL DEFAULT 1,
    deleted    INT          NOT NULL DEFAULT 0,
    created_at TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP
);
-- 边界框查询（lng BETWEEN ? AND ? AND lat BETWEEN ? AND ?）走这个联合索引
CREATE INDEX IF NOT EXISTS idx_geo_point_lnglat ON geo_point (lng, lat);

-- ---------------------------------------------------------------------
-- 活动 / 场次 / 报名
-- ---------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS activity (
    id                BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    title             VARCHAR(200) NOT NULL,
    cover_url         VARCHAR(500),
    region_id         BIGINT,
    description       CLOB,
    status            INT          NOT NULL DEFAULT 1,
    signup_start_time TIMESTAMP,
    signup_end_time   TIMESTAMP,
    start_time        TIMESTAMP,
    end_time          TIMESTAMP,
    deleted           INT          NOT NULL DEFAULT 0,
    created_at        TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_activity_status ON activity (status, deleted);

CREATE TABLE IF NOT EXISTS activity_session (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    activity_id BIGINT       NOT NULL,
    name        VARCHAR(100) NOT NULL,
    start_time  TIMESTAMP,
    end_time    TIMESTAMP,
    capacity    INT          NOT NULL DEFAULT 0,
    remain      INT          NOT NULL DEFAULT 0,
    price       DECIMAL(10, 2) NOT NULL DEFAULT 0.00,
    -- 乐观锁版本号：必须有默认值，否则 MyBatis-Plus 生成的 update 条件会带上 null
    version     INT          NOT NULL DEFAULT 0,
    created_at  TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_activity_session_activity ON activity_session (activity_id);

CREATE TABLE IF NOT EXISTS activity_signup (
    id            BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    session_id    BIGINT      NOT NULL,
    activity_id   BIGINT      NOT NULL,
    user_id       BIGINT      NOT NULL,
    contact_name  VARCHAR(64) NOT NULL,
    contact_phone VARCHAR(20) NOT NULL,
    code          VARCHAR(32) NOT NULL,
    status        INT         NOT NULL DEFAULT 1,
    signup_time   TIMESTAMP   NOT NULL DEFAULT CURRENT_TIMESTAMP,
    verify_time   TIMESTAMP,
    verify_by     BIGINT,
    remark        VARCHAR(255),
    created_at    TIMESTAMP   NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE UNIQUE INDEX IF NOT EXISTS uk_activity_signup_code ON activity_signup (code);
-- 带上 status：允许"取消后重新报名"，同时把并发重复报名交给数据库兜底
CREATE UNIQUE INDEX IF NOT EXISTS uk_activity_signup_session_user ON activity_signup (session_id, user_id, status);
CREATE INDEX IF NOT EXISTS idx_activity_signup_user ON activity_signup (user_id, created_at);

CREATE TABLE IF NOT EXISTS signup_verify_log (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    signup_id   BIGINT      NOT NULL,
    operator_id BIGINT,
    action      VARCHAR(16) NOT NULL,
    result      VARCHAR(16) NOT NULL,
    remark      VARCHAR(255),
    created_at  TIMESTAMP   NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_signup_verify_log_signup ON signup_verify_log (signup_id);

-- ---------------------------------------------------------------------
-- AI 会话 / 操作日志
-- ---------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS ai_conversation (
    id            BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id       BIGINT       NOT NULL,
    title         VARCHAR(200) NOT NULL,
    scene         VARCHAR(32)  NOT NULL DEFAULT 'assistant',
    message_count INT          NOT NULL DEFAULT 0,
    created_at    TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at    TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_ai_conversation_user ON ai_conversation (user_id, created_at);

CREATE TABLE IF NOT EXISTS ai_message (
    id                BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    conversation_id   BIGINT      NOT NULL,
    msg_role          VARCHAR(16) NOT NULL,
    content           CLOB        NOT NULL,
    provider          VARCHAR(32),
    model             VARCHAR(64),
    prompt_tokens     INT,
    completion_tokens INT,
    latency_ms        BIGINT,
    created_at        TIMESTAMP   NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_ai_message_conversation ON ai_message (conversation_id, id);

CREATE TABLE IF NOT EXISTS operation_log (
    id         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    trace_id   VARCHAR(32),
    user_id    BIGINT,
    username   VARCHAR(64),
    action     VARCHAR(64),
    method     VARCHAR(8),
    path       VARCHAR(255),
    ip         VARCHAR(64),
    cost_ms    BIGINT,
    success    INT  NOT NULL DEFAULT 1,
    detail     VARCHAR(1000),
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_operation_log_created ON operation_log (created_at);
